"""Shared location and traversal helpers for the documentation gate."""

from __future__ import annotations

from pathlib import Path

# Directories generated by tools and never hand-edited, so they cannot carry governed documents.
# Matching is per path segment, so only a directory named build is skipped; `docs/build.md` is unaffected.
# No configuration entry: these names are decided by tools, not by the project.
_SKIP_DIRS = {
    # Version control and dependencies
    ".git",
    "node_modules",
    "vendor",
    ".venv",
    "venv",
    ".eggs",
    # Python tool caches
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    ".tox",
    ".nox",
    # Build output
    "build",
    "dist",
    # Artifacts from other language ecosystems
    "target",
    ".next",
    ".nuxt",
    ".gradle",
}


def repo_root() -> Path:
    """Return the repository root: three levels up from `.agents/scripts/checks/`."""
    return Path(__file__).resolve().parents[3]


def rel(root: Path, path: Path) -> str:
    """Return a POSIX path relative to the repository root, for stable printing."""
    return str(path.relative_to(root)).replace("\\", "/")


# Documents live in the repository-root `*.md` plus the docs/, .agents/, and .changes/ trees. The rest of
# the repository is not scanned: stray notes in the source tree and gitignored cache directories are not
# documents, and applying the layout rules to them would raise the cost of adopting this in a real
# repository beyond what anyone would pay.
_DOC_TREES = ("docs", ".agents", ".changes")


def skipped(root: Path, path: Path) -> bool:
    """Return whether a path sits in a tool-generated, never hand-edited directory."""
    return any(part in _SKIP_DIRS for part in path.relative_to(root).parts)


def documents(root: Path, skip_archived: bool = False):
    """Yield governed markdown: root `*.md`, docs/, .agents/, and .changes/.

    @param root Repository root.
    @param skip_archived When true, skip `.changes/archive/`, the frozen historical snapshots.
    """
    for path in sorted(root.glob("*.md")):
        if path.is_file():
            yield path
    for name in _DOC_TREES:
        base = root / name
        if not base.is_dir():
            continue
        for path in sorted(base.rglob("*.md")):
            if skipped(root, path):
                continue
            parts = path.relative_to(root).parts
            if skip_archived and "/".join(parts).startswith(".changes/archive/"):
                continue
            yield path


def report(name: str, errors: list[str]) -> bool:
    """Print one validator's result and return whether it passed."""
    if errors:
        print(f"[FAIL] {name}")
        for error in errors:
            print(f"    - {error}")
        return False
    print(f"[PASS] {name}")
    return True
